		Menu::AddLetter(menuVP_5150v2_p23, "q", "Smack You in the Mouth", "say(0, \"I'LL SMACK U IN THE MOUTH, I'M NEIL DIAMOND.  Ok that's it, I'm gone.  That's it.  Wait!~wsmack\");");
		Menu::AddLetter(menuVP_5150v2_p23, "r", "Gave the Money Back", "say(0, \"Fine would it help if we gave the money back?  YES, IT WOULD.  CUZ WE DON'T HAVE IT.~wmback\");");
		Menu::AddLetter(menuVP_5150v2_p23, "s", "EVERYONE SHUTUP", "say(0, \"EVERYONE NEEDS TO SHUT UP.  SHUT UP.  YOU GUYS SHUT UP.  YOU SHUT YOUR MOUTH.  YOU'VE RUINED MY WEDDING.~wshutup\");");
		Menu::AddLetter(menuVP_5150v2_p23, "t", "Wade Would Kill a Dog", "say(0, \"But Wade told me for 50 dollars, he'd kill a dog.  *BAM*  I did NOT tell him that.~wtell\");");
		Menu::AddLetter(menuVP_5150v2_p23, "u", "Dog in Hell", "say(0, \"Look.  Am I happy that that dog is rotting in hell?  Yes.  Did I personally inject a steak with poison and feed it to the dog?  No.~wpoison\");");
		Menu::AddLetter(menuVP_5150v2_p23, "v", "Dodge Stratus", "say(0, \"I drive....I drive....I DRIVE A DODGE STRATUS.~wdodge\");");
		Menu::AddLetter(menuVP_5150v2_p23, "w", "I Like Hispanic Men", "say(0, \"I like the meat of young hispanic men.  That's because you're gay.  Maybe I am....and maybe I AM.~whispanic\");");
		Menu::AddLetter(menuVP_5150v2_p23, "x", "OH REALLY?", "say(0, \"OH REALLY?  Then where did THIS tasty lick come from?  *Plink!* *Plink!* *Plink!* *Plink!* *Plink!* *Plink!*~wlick\");");
		Menu::AddLetter(menuVP_5150v2_p23, "y", "How Hot is it?", "say(0, \"HEY, How hot is it?  Unbearable!  How hot is it?!  Unbearable!  Huh, how hot is it?!?  Unbearable!  OOooh!!~whowhot\");");
		Menu::AddLetter(menuVP_5150v2_p23, "z", "I'm The Devil", "say(0, \"Not only have I shed 65lbs in 4 days, but guess what?!?  I FOUND OUT I'M THE DEVIL.~wtango\");");
		Menu::AddLetter(menuVP_5150v2_p23, "1", "Favorite Planet", "say(0, \"Hey!  Let me ask, what's yer favorite planet?~wplanet\");");
		Menu::AddLetter(menuVP_5150v2_p23, "2", "Favorite Planet 2", "say(0, \"I..I..E, I don't have a favorite uh....I find them all fascinating, they're all part of uh..MINES the sun!~wplanet2\");");
		Menu::AddLetter(menuVP_5150v2_p23, "3", "Favorite Planet 3", "say(0, \"Always has been.  I like it cuz it's like the King of Planets.~wplanet3\");");
		Menu::AddLetter(menuVP_5150v2_p23, "4", "Favorite Planet 4", "say(0, \"Actually Harry it's not uh...not a planet it's a star.  Well planet or star, when that thing burns out we're all gonna be dead.~wplanet4\");");
		Menu::AddLetter(menuVP_5150v2_p23, "5", "Favorite Planet 5", "say(0, \"Hey, Doctor...have ya ever seen an eclipse?  Uh...ss, y..y..ya I've seen many, yes.~wplanet5\");");
		Menu::AddLetter(menuVP_5150v2_p23, "6", "Favorite Planet 6", "say(0, \"You know if you stare at it head on, it'll burn yer eyes out.  Well it's not, not, not best to stare at the sun during an eclipse.  But it's hard not to.~wplanet6\");");
		Menu::AddLetter(menuVP_5150v2_p23, "7", "Favorite Planet 7", "say(0, \"I once took a pair of binoculars and stared at the sun fer, over an hour.~wsun\");");
		Menu::AddLetter(menuVP_5150v2_p23, "8", "Favorite Planet 8", "say(0, \"Why would you do that?  Curiosity I guess.  Heck, I'm curious like a cat.~wsun2\");");
		Menu::AddLetter(menuVP_5150v2_p23, "9", "Hepatitis Test", "say(0, \"Well that's cool.  I just took a test this morning.  Yea, at the free clinic for Hepatitis.~whepa1\");");
		Menu::AddLetter(menuVP_5150v2_p23, "0", "Hepatitis Test 2", "say(0, \"I kicked ass too.  I got an A...two B's and a C.~whepa2\");");
