		Menu::AddLetter(menuVP_5150v2_p24, "4", "Mad Cow Disease 4", "say(0, \"Hey, what about this?  If you had a choice between being the top scientist in your field, or gettin Mad Cow Disease, what would it be?~wmcow4\");");
