		Menu::AddLetter(menuVP_5150v2_p27, "o", "How High - Pledge Allegiance", "say(0, \"I pledge allegiance to da pimp, of the united pimps of America.  *slap!*~wpledge\");");
		Menu::AddLetter(menuVP_5150v2_p27, "p", "How High - Pimpology", "say(0, \"Today's class is called Pimpology 1 and 2.  I'm 1, that's 2.~wpimpol\");");
		Menu::AddLetter(menuVP_5150v2_p27, "q", "How High - Come out Right", "say(0, \"It got to come out right.  And if don't come out right, you ain't gonna get da pimp tonight.~wpimpin7\");");
