		Menu::AddLetter(menuVP_5150v2_p27, "t", "Joe Dirt - Buffalo Bob", "say(0, \"'m only doing all of this cuz I heard that that Buffalo Bob guy shoved a road flare up yer bunghole.  WHAAAAT?  *HOO-RAH*~wflare\");");
		Menu::AddLetter(menuVP_5150v2_p27, "u", "Joe Dirt - A Fork?", "say(0, \"You got like warm water and - A FORK! Yeah. NO! Owww. What?~wfork\");");
		Menu::AddLetter(menuVP_5150v2_p27, "v", "Joe Dirt - Puts the Lotion on", "say(0, \"It puts the lotion on.  You have NO IDEA WHAT KIND OF HELL I CAN BRING YOU.  OOOohhh alriiiiight, enuf ya broken record, ok.~wlotion\");");
		Menu::AddLetter(menuVP_5150v2_p27, "w", "Joe Dirt - Puts the Lotion on 2", "say(0, \"It puts the lotion on its skin.  NOW.  Well, say it don't spray it brother, daaang.  I need a TOWEL now.  IT DOES WHAT ITS TOLD.~wlotion2\");");
		Menu::AddLetter(menuVP_5150v2_p27, "x", "Joe Dirt - Ain't no Meteor", "say(0, \"It ain't no meteor, this is a big ol frozen chunk a shit.  *WHAAA?*  Oh ya.~wmeteor\");");
		Menu::AddLetter(menuVP_5150v2_p27, "y", "Joe Dirt - Septic Tank", "say(0, \"Ewww!  Take it away!  Stop it!  Somebody help me.~wseptic\");");
		Menu::AddLetter(menuVP_5150v2_p27, "z", "Joe Dirt - Septic Tank 2", "say(0, \"Help me!  Ewww.  Is it done?  How much is in there?~wseptic2\");");
		Menu::AddLetter(menuVP_5150v2_p27, "1", "Joe Dirt - What you say?", "say(0, \"What'd you say?  Oohh.  Yer talkin to me all wrong.  It's...it's the wrong tone.  You do it again....I'll stab you in the face with a sodering iron.~wsoder\");");
