		Menu::AddLetter(menuVP_5150v2_p28, "a", "Office Space - Hey Guys", "say(0, \"Hey guys.  wsUP g.~wsupg2\");");
		Menu::AddLetter(menuVP_5150v2_p28, "b", "Office Space - wsUP g", "say(0, \"wsUP g.~wsupg\");");
		Menu::AddLetter(menuVP_5150v2_p28, "c", "Office Space - Pronounce Name", "say(0, \"No one in this country can ever pronounce my name right.  Aie, it's..it's not that hard.  Ni-E-Nana-Ja.  Nienanaja.  Yeah well at least your name isn't Michael Bolton.~wbolton2\");");
		Menu::AddLetter(menuVP_5150v2_p28, "d", "Office Space - Ass Clown", "say(0, \"You know there's nothing wrong with that name.  There *WAS* nothing wrong with it.  Until I was about 12 years old and that no-talent ass clown became famous and started winning Grammy's.~wbolton3\");");
		Menu::AddLetter(menuVP_5150v2_p28, "e", "Office Space - Go By Mike", "say(0, \"Why don't you just uh...go by Mike, instead of Michael?  No way.  Why should I change?  He's the one who sucks.~wbolton4\");");
		Menu::AddLetter(menuVP_5150v2_p28, "f", "Office Space - Real Name?", "say(0, \"Is that your real name?  Yeah.  Are you any relation to the pop singer?  No it's just a coincedence.  Because I'll be honest with ya, I love his music!~wbolton5\");");
		Menu::AddLetter(menuVP_5150v2_p28, "g", "Office Space - Bolton Fan", "say(0, \"I do, I'm a Michael Bolton fan.  For my money, I don't know if it gets any better than when he sings When a Man Loves a Woman.~wbolton6\");");
		Menu::AddLetter(menuVP_5150v2_p28, "h", "Office Space - Fudgepackers", "say(0, \"I told those fudgepackers I like Michael Bolton's music.  Oh....that is not right Michael.~wbolton7\");");
		Menu::AddLetter(menuVP_5150v2_p28, "i", "Office Space - Not Gonna Work", "say(0, \"We're gonna be getting rid of these people here, uh...first Mr. Samere Nagahhheeee..yuh Naga...Naga...not gonna work here anymore anyway.  HAHAHA.~wnotg\");");
		Menu::AddLetter(menuVP_5150v2_p28, "j", "Office Space - PC Load Letter?", "say(0, \"That yer supposed to figure out what you would..want to do if....PC Load Letter?  WTF does that mean?~wpcload\");");
		Menu::AddLetter(menuVP_5150v2_p28, "k", "Office Space - Paper Jam", "say(0, \"No, not again I....WHY does it say paper jam when there IS no paper jam.  I swear ah one of these days I..I..I..I just kick this piece of sh*t out the window.~wpjam\");");
		Menu::AddLetter(menuVP_5150v2_p28, "l", "Office Space - The Trick is", "say(0, \"He says the trick is, kick someone's ass the first day or become someone's bitch.  Then everything will be alright.~wtrick\");");
		Menu::AddLetter(menuVP_5150v2_p28, "m", "Office Space - MOTHER SHITTER", "say(0, \"MOTHER SHITTER.  SONUVA...ASS.  MMMOO...I JUS *BANG* *BANG* *BANG*~wmother\");");
		Menu::AddLetter(menuVP_5150v2_p28, "n", "Office Space - The Monday's", "say(0, \"Uh oh!  Sounds like somebody's got a case of the Moondays!~wmoondays\");");
		Menu::AddLetter(menuVP_5150v2_p28, "o", "Office Space - OOhh...yeah", "say(0, \"OOhh...yeah.  Ummm...I'm gonna have to go ahead and sort of disagree with you there.  Yeah.~whmmm\");");
		Menu::AddLetter(menuVP_5150v2_p28, "p", "Office Space - Cornhole", "say(0, \"Hey Peter.  Yeah?  Watch out for your cornhole bud.  Ok Lawrence.~wcornh\");");
		Menu::AddLetter(menuVP_5150v2_p28, "q", "Office Space - Radio", "say(0, \"Well, I..I was told that I could listen to the radio at a reasonable volume.~wradio\");");
		Menu::AddLetter(menuVP_5150v2_p28, "r", "Office Space - Radio 2", "say(0, \"Well, I..I..I..I told Bill that if if Sandra's going to listen to her headphones while she..while she's filing, then I should be able to listen to the radio while I'm collating, so I don't see why I should have to turn down the radio because....~wradio2\");");
		Menu::AddLetter(menuVP_5150v2_p28, "s", "Office Space - Talk To Payroll", "say(0, \"Mr. Lumbergh told me talk to payroll, and then payroll told me to talk to Mr. Lumbergh.  And I, I still haven't received my paycheck.  And he took my stapler.~wstapler2\");");
		Menu::AddLetter(menuVP_5150v2_p28, "t", "Office Space - Moved My Desk", "say(0, \"And he never brought it back.  And then they moved my desk to storage room D, and there was garbage on it.~wstapler3\");");
